function reportCardParseErrors(errors: CardParseError[]) {
    const paths = errors.map(({ path }) => path).join(', ')
    dialogService.warning(`Some project files could not be loaded and were skipped: ${paths}`, { title: 'Some cards were not loaded' })
    errors.forEach(({ error }) => telemetryService.captureError(error))
}

function eventCard(card: ProjectSnapshot['activeCards'][number]) {
    return {
        ...card,
        header: {
            ...card.header,
            affects: [...card.header.affects],
            agentLogReferences: [...card.header.agentLogReferences],
            policy: { ...card.header.policy },
        },
    }
}

function isSameArray<T>(first: readonly T[], second: readonly T[]) {
    return first === second || (first.length === second.length && second.every((value, index) => first[index] === value))
}

function isSamePolicy(first: Record<string, boolean>, second: Record<string, boolean>) {
    if (first === second) return true
    const entries = Object.entries(second)

    return Object.keys(first).length === entries.length && entries.every(([key, value]) => first[key] === value)
}

function cardFieldChanged(field: CardField, previousCard: CardAddedEventDetail['card'], card: CardAddedEventDetail['card']) {
    const previousHeader = previousCard.header
    const header = card.header
    if (field === 'affects') return !isSameArray(previousHeader.affects, header.affects)
    if (field === 'body') return previousCard.content !== card.content
    if (field === 'conversation') {
        return !isSameArray(previousCard.agentConversations, card.agentConversations)
            || !isSameArray(previousCard.agentConversationErrors, card.agentConversationErrors)
            || !isSameArray(previousHeader.agentLogReferences, header.agentLogReferences)
    }
    if (field === 'identity') {
        return previousHeader.id !== header.id
            || previousHeader.internalId !== header.internalId
            || previousCard.isActive !== card.isActive
            || previousCard.path !== card.path
    }
    if (field === 'ordering') return previousHeader.after !== header.after || previousHeader.status !== header.status
    if (field === 'policy') return !isSamePolicy(previousHeader.policy, header.policy)
    if (field === 'status') return previousHeader.status !== header.status
    if (field === 'title') return previousHeader.title !== header.title

    return previousHeader.worktree !== header.worktree
        || previousHeader.worktreeError !== header.worktreeError
        || previousHeader.worktreeValue !== header.worktreeValue
}

async function flushAggregatePendingChanges() {
    const persistenceService = getService<{ flushPendingChanges(): Promise<void> }>('projectPersistenceService')
    await persistenceService.flushPendingChanges()
}

export class DataService extends EventTarget {
    readonly agents: AgentIntegration
    readonly cards: CardOperations
    readonly projectLoading: ProjectLoading
    readonly releases: ReleaseOperations

    private commitBatcher: CommitBatcher | null = null
    private remarkableBridge: RemarkableBridge | null = null
    private storage: StorageService | null = null
    private readonly projectState: ProjectState
    private readonly saveStateService: SaveStateService
    private persistenceSnapshot: DataPersistenceSnapshot = { hasPendingFileCommit: false, hasPendingPush: false, isSaving: false }

    constructor() {
        super()
        this.saveStateService = new SaveStateService()
        this.saveStateService.addEventListener('changed', () => this.dispatchPersistenceChanged())
        this.projectState = new ProjectState(
            (card) => this.agents.attachCardAgentConversations(card),
            (previousCards, nextCards) => this.dispatchCardChanges(previousCards, nextCards),
            reportCardParseErrors,
        )
        this.cards = new CardOperations(
            this.createCardOperationsDependencies(),
            (cardPath, state) => {
                this.agents.triggerStateActions(cardPath, state)
                const snapshot = this.projectState.snapshot
                const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
                    .find(({ path }) => path === cardPath)
                void notifyActionCardStateChange(card?.header.internalId ?? null, state).catch((error: unknown) => {
                    dialogService.error(error, { fallbackMessage: 'Could not update automatic agent finish' })
                })
            },
        )
        this.agents = new AgentIntegration(
            this.createAgentIntegrationDependencies(),
            (cardPath, reference) => this.cards.addAgentLogReference(cardPath, reference),
        )
        agentAcknowledgementService.connectConversationStore((conversation) => this.agents.findStoredConversation(conversation))
        this.projectLoading = new ProjectLoading(
            this.createProjectLoadingDependencies(),
            (projectLoadToken) => this.agents.prepareProjectConversationLoad(projectLoadToken),
        )
        this.releases = new ReleaseOperations(this.createReleaseOperationsDependencies(), () => this.cards.flushPendingCommits())
        agentConversationService.subscribe(() => this.dispatchChanged())
        register('dataService', this)
    }

    init(dependencies: DataServiceDependencies) {
        this.projectLoading.reset()
        this.agents.reset()
        this.projectState.resetLoadedProject()
        this.remarkableBridge = dependencies.remarkableBridge ?? null
        this.storage = withSaveStateTracking(dependencies.storage, this.saveStateService)
        this.initializeStorageServices()
        worktreeService.init({
            assignCardWorktree: (path, worktree, branch) => this.cards.assignCardWorktree(path, worktree, branch),
            cardSeparatorProvider: () => this.requireDependencies().config.cardSeparator,
            clearCardBranch: (path) => this.cards.clearCardBranch(path),
            flushPendingChanges: flushAggregatePendingChanges,
            projectFolderProvider: () => this.requireDependencies().config.projectFolder,
            projectProvider: () => this.projectState.project,
            snapshotProvider: () => this.projectState.snapshot,
            storageProvider: () => this.storage,
            unassignCardWorktree: (path) => this.cards.updateCardWorktree(path, null),
        })
        this.agents.startScheduledRunWatch()
        const delayMs = configService.get('react.autoCommitDelayMs')
        this.commitBatcher = new CommitBatcher(this.cards, delayMs)
        this.commitBatcher.addEventListener(
            COMMIT_BATCHER_FLUSH_FAILED_EVENT,
            (event) => this.reportCommitFlushFailure((event as CustomEvent<unknown>).detail),
        )
        this.commitBatcher.addEventListener(
            COMMIT_BATCHER_PENDING_CHANGED_EVENT,
            () => this.dispatchPersistenceChanged(),
        )
        this.dispatchChanged()
        this.dispatchPersistenceChanged()
    }

    /** Replace remote transport while preserving loaded project and its in-memory state. */
    replaceRemoteStorage(storage: StorageService) {
        if (!this.storage || !this.projectState.project) throw new Error('Cannot replace storage without a loaded project')

        this.storage = withSaveStateTracking(storage, this.saveStateService)
        this.initializeStorageServices()
        this.projectLoading.restartProjectWatch()
    }

    getState(): DataServiceState {
        return {
            project: this.projectState.project,
            runningAgents: agentConversationService.getRunningAgents(),
            snapshot: this.projectState.snapshot,
        }
    }

    getPersistenceSnapshot(): DataPersistenceSnapshot {
        const currentProject = this.projectState.project

        return {
            hasPendingFileCommit: this.commitBatcher?.hasPending() ?? false,
            hasPendingPush: currentProject ? this.storage?.hasPendingPush?.(currentProject) ?? false : false,
            isSaving: this.saveStateService.getState().isSaving,
        }
    }

    async drainPendingStorageWrites() {
        await this.saveStateService.drain()
    }

    getConfig(): ProjectConfig | null {
        return getProjectConfigOrNull(this.storage)
    }
    async listAgentConversations(context: ActionContext) {
        if (context.kind === 'project') return this.agents.listProjectAgentConversations()
        if (!context.cardInternalId) throw new Error(`Missing cardInternalId for ${context.kind} agent conversation context`)

        return this.agents.ensureAgentConversationsForCard(context.cardInternalId)
    }
    async loadAgentConversation(path: string) {
        const { storage } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot load an agent conversation before a project is open')

        return loadAgentConversation(storage, currentProject, path)
    }
    async persistActionFile(
        file: MarkdownFile,
        sourcePath = file.path,
        onPathCommitted?: (fromPath: string, toPath: string) => void,
        sourceExists = true,
        saveReference?: OpenDocumentSaveReference,
        onPersisted?: () => void,
    ) {
        const { commitBatcher } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot save an action before a project is open')

        if (sourceExists && sourcePath === file.path) {
            commitBatcher.schedule(currentProject.branch, [{ ...file, onPersisted, saveReference }], `Update ${file.path}`)
        } else {
            if (!onPathCommitted) throw new Error(`Missing action path callback for rename from ${sourcePath} to ${file.path}`)
            commitBatcher.schedulePathChange(
                currentProject.branch,
                sourcePath,
                { ...file, onPersisted, saveReference },
                `Rename ${sourcePath} to ${file.path}`,
                onPathCommitted,
                sourceExists,
            )
        }
    }

    discardPendingFile(path: string) {
        const { commitBatcher } = this.requireDependencies()
        commitBatcher.discardPendingFile(path)
    }

    hasPendingFile(path: string) {
        const { commitBatcher } = this.requireDependencies()

        return commitBatcher.hasPendingFile(path)
    }

    getRemarkableMetadataContent(): string | null {
        const config = this.getConfig()
        if (!config) return null
        return getRemarkableMetadataContent(this.projectState.files, config)
    }
    async importRemarkableImages(request: RemarkableImportInput): Promise<RemarkableImportPlan> {
        const { config, storage } = this.requireDependencies()
        const currentProject = this.projectState.project
        if (!currentProject) throw new Error('Cannot import Remarkable images before a project is open')
        const plan = await importRemarkableImages({
            bridge: this.remarkableBridge,
            commitAndMergeFiles: (commitRequest, fallbackFiles) => this.cards.commitAndMergeFiles(commitRequest, fallbackFiles),
            config,
            files: this.projectState.files,
            project: currentProject,
            request,
            storage,
        })
        this.refreshSnapshot(config.workingFolder)
        telemetryService.trackEvent('remarkable_import')
        return plan
    }
    private createCardOperationsDependencies(): CardOperationsDeps {
        return {
            addRepositoryFile: (path) => this.projectState.addRepositoryFile(path),
            applyMoves: (moves, workingFolder) => this.projectState.applyMoves(moves, workingFolder),
            cardPathChanged: (fromPath, toPath) => this.dispatchCardPathChanged(fromPath, toPath),
            dispatchChanged: () => this.dispatchChanged(),
            dispatchPersistenceChanged: () => this.dispatchPersistenceChanged(),
            commitPathsInFlight: () => this.projectState.commitPathsInFlight,
            deleteFile: (path, committedFiles, workingFolder) => (
                this.projectState.deleteFile(path, committedFiles, workingFolder)
            ),
            files: () => this.projectState.files,
            mergeCommittedFiles: (files, workingFolder) => this.projectState.mergeCommittedFiles(files, workingFolder),
            mutateCard: (path, mutation, workingFolder) => this.projectState.mutateCard(path, mutation, workingFolder),
            project: () => this.projectState.project,
            recordCurrentContent: (files) => this.projectState.recordCurrentContent(files),
            refreshSnapshot: (workingFolder) => this.refreshSnapshot(workingFolder),
            reloadCurrentProjectSnapshot: () => this.projectLoading.reloadCurrentProjectSnapshot(),
            removeFolder: (path, workingFolder) => this.projectState.removeFolder(path, workingFolder),
            renameFile: (fromPath, toPath, workingFolder) => this.projectState.renameFile(fromPath, toPath, workingFolder),
            requireDependencies: () => this.requireDependencies(),
            requireCard: (path) => this.projectState.requireCard(path),
            requireCardByInternalId: (internalId) => this.projectState.requireCardByInternalId(internalId),
            requireFile: (path) => this.projectState.requireFile(path),
            replaceFiles: (files, workingFolder) => this.projectState.replaceFiles(files, workingFolder),
            snapshot: () => this.projectState.snapshot,
            updateFiles: (updatedFiles, removedPaths, workingFolder) => (
                this.projectState.updateFiles(updatedFiles, removedPaths, workingFolder)
            ),
        }
    }

    private createAgentIntegrationDependencies(): AgentIntegrationDeps {
        return {
            beginAgentConversationLoad: () => this.projectState.beginAgentConversationLoad(),
            isCurrentAgentConversationLoad: (agentConversationLoadToken) => (
                this.projectState.isCurrentAgentConversationLoad(agentConversationLoadToken)
            ),
            isCurrentLoad: (project, projectLoadToken) => this.projectState.isCurrentLoad(project, projectLoadToken),
            project: () => this.projectState.project,
            refreshCardConversations: (path, workingFolder) => (
                this.projectState.refreshCardConversations(path, workingFolder)
            ),
            requireDependencies: () => this.requireDependencies(),
            snapshot: () => this.projectState.snapshot,
            conversationChanged: (cardPath) => this.dispatchEvent(new Event(cardFieldChangedEvent(cardPath, 'conversation'))),
        }
    }

    private createProjectLoadingDependencies(): ProjectLoadingDeps {
        return {
            beginProjectLoad: () => this.projectState.beginProjectLoad(),
            clearLoadedProject: () => this.projectState.resetLoadedProject(),
            commitPathsInFlight: () => this.projectState.commitPathsInFlight,
            dispatchChanged: () => this.dispatchChanged(),
            dispatchPersistenceChanged: () => this.dispatchPersistenceChanged(),
            dispatchRepositoryChanged: (event) => this.dispatchEvent(new CustomEvent('repositoryChanged', { detail: event })),
            files: () => this.projectState.files,
            flushPendingChanges: flushAggregatePendingChanges,
            matchesCurrentContent: (path, content) => this.projectState.matchesCurrentContent(path, content),
            isCurrentLoad: (project, projectLoadToken) => this.projectState.isCurrentLoad(project, projectLoadToken),
            mergeBackgroundProjectFiles: (files, workingFolder, repositoryFiles) => (
                this.projectState.mergeBackgroundProjectFiles(files, workingFolder, repositoryFiles)
            ),
            project: () => this.projectState.project,
            replaceFiles: (files, workingFolder) => this.projectState.replaceFiles(files, workingFolder),
            replaceProject: (project) => this.projectState.replaceProject(project),
            ensureCardInternalIds: async () => {
                if (this.cards.ensureCardInternalIds() > 0) await this.cards.flushPendingCommits()
            },
            replaceProjectFiles: (files, workingFolder, repositoryFiles) => (
                this.projectState.replaceProjectFiles(files, workingFolder, repositoryFiles)
            ),
            updateFiles: (updatedFiles, removedPaths, workingFolder) => (
                this.projectState.updateFiles(updatedFiles, removedPaths, workingFolder)
            ),
            updateRepositoryFile: (event) => this.projectState.updateRepositoryFile(event),
            requireDependencies: () => this.requireDependencies(),
            resetAgentConversations: () => this.agents.resetLoadedConversations(),
            snapshot: () => this.projectState.snapshot,
            storage: () => this.storage,
        }
    }

    private createReleaseOperationsDependencies(): ReleaseOperationsDeps {
        return {
            applyMoves: (moves, workingFolder) => this.projectState.applyMoves(moves, workingFolder),
            dispatchChanged: () => this.dispatchChanged(),
            files: () => this.projectState.files,
            project: () => this.projectState.project,
            requireDependencies: () => this.requireDependencies(),
            snapshot: () => this.projectState.snapshot,
        }
    }

    private refreshSnapshot(workingFolder: string) {
        this.projectState.refreshSnapshot(workingFolder)
        this.dispatchChanged()
    }
    private initializeStorageServices() {
        if (!this.storage) throw new Error('Data service storage is not initialized')

        mergeConflictService.init({
            completeBranchCleanup: (cardInternalId) => {
                const snapshot = this.projectState.snapshot
                const card = [...(snapshot?.activeCards ?? []), ...(snapshot?.backgroundCards ?? [])]
                    .find((candidate) => candidate.header.internalId === cardInternalId)
                if (!card) return
                this.cards.updateCardWorktree(card.path, null)
                this.cards.clearCardBranch(card.path)
            },
            reloadPaths: (paths) => this.projectLoading.reloadConflictPaths(paths),
            reportError: (error) => dialogService.error(error, { fallbackMessage: 'Could not verify merge conflict state' }),
            storage: this.storage,
        })
    }
    private reportCommitFlushFailure(error: unknown) {
        reportCommitFlushFailure(error, () => this.dispatchPersistenceChanged())
    }
    private requireDependencies() {
        if (!this.storage) throw new Error('Data service storage is not initialized')
        if (!this.commitBatcher) throw new Error('Data service commit batcher is not initialized')
        const config = resolveProjectConfigPaths(configService.getProjectConfig())
        return { commitBatcher: this.commitBatcher, config, storage: this.storage }
    }
    private dispatchChanged() {
        this.dispatchPersistenceChanged()
        this.dispatchEvent(new CustomEvent<DataServiceState>('changed', { detail: this.getState() }))
    }
    private dispatchCardPathChanged(fromPath: string, toPath: string) {
        const detail: CardPathChangedEventDetail = { fromPath, toPath }
        this.dispatchEvent(new CustomEvent<CardPathChangedEventDetail>(CARD_PATH_CHANGED_EVENT, { detail }))
    }
    private dispatchCardChanges(
        previousCards: ProjectSnapshot['activeCards'],
        nextCards: ProjectSnapshot['activeCards'],
    ) {
        const previousByPath = new Map(previousCards.map((card) => [card.path, card]))
        const nextByPath = new Map(nextCards.map((card) => [card.path, card]))
        for (const card of previousCards) {
            if (!nextByPath.has(card.path)) {
                this.dispatchEvent(new CustomEvent<CardRemovedEventDetail>(CARD_REMOVED_EVENT, { detail: { card: eventCard(card) } }))
            }
        }
        for (const card of nextCards) {
            const previousCard = previousByPath.get(card.path)
            if (!previousCard) {
                this.dispatchEvent(new CustomEvent<CardAddedEventDetail>(CARD_ADDED_EVENT, { detail: { card: eventCard(card) } }))
            } else if (previousCard !== card) {
                const detail = { card: eventCard(card), previousCard: eventCard(previousCard) }
                this.dispatchEvent(new CustomEvent<CardChangedEventDetail>(CARD_CHANGED_EVENT, { detail }))
                for (const field of CARD_FIELDS) {
                    if (!cardFieldChanged(field, previousCard, card)) continue
                    this.dispatchEvent(new Event(cardFieldChangedEvent(card.path, field)))
                    this.dispatchEvent(new Event(cardCollectionFieldChangedEvent(field)))
                }
                if (previousCard.header.status !== card.header.status && card.header.status) {
                    const finishNotification = notifyActionCardStateChange(card.header.internalId, card.header.status)
                    void finishNotification.catch((error: unknown) => {
                        dialogService.error(error, { fallbackMessage: 'Could not update automatic agent finish' })
                    })
                }
            }
        }
    }
    private dispatchPersistenceChanged() {
        const nextSnapshot = this.getPersistenceSnapshot()
        if (DataService.isSamePersistenceSnapshot(this.persistenceSnapshot, nextSnapshot)) return

        this.persistenceSnapshot = nextSnapshot
        this.dispatchEvent(new CustomEvent<DataPersistenceSnapshot>('persistenceChanged', { detail: nextSnapshot }))
    }
    private static isSamePersistenceSnapshot(first: DataPersistenceSnapshot, second: DataPersistenceSnapshot) {
        return first.hasPendingFileCommit === second.hasPendingFileCommit
            && first.hasPendingPush === second.hasPendingPush
            && first.isSaving === second.isSaving
    }
}

export const dataService = new DataService()

import type { CommitBatcher } from '../../data/commit_batcher'
import type {
    MarkdownFile,
    ProjectConfig,
    StorageService,
} from '../../data/data_types'
import { resolveProjectConfigPaths } from '../../data/data_types'
import type { RemarkableBridge } from '../../data/remarkable_bridge'
import { configService } from '../config/config_service'
import { dialogService } from '../dialog_service'
import { telemetryService } from '../telemetry/telemetry_service'

export interface DataServiceDependencies {
    remarkableBridge?: RemarkableBridge
    storage: StorageService
}

export interface RequiredDataServiceDependencies {
    commitBatcher: CommitBatcher
    config: ProjectConfig
    storage: StorageService
}

export function errorMessage(error: unknown, fallback: string) {
    return error instanceof Error ? error.message : fallback
}

export function reportWorkspaceError(message: string) {
    dialogService.error(message)
}

export function reportWorkspaceNotice(message: string) {
    dialogService.success(message)
}

/** Merge committed files into loaded files: replace matching paths, append new paths. */
export function mergeFiles(current: MarkdownFile[], updates: MarkdownFile[]): MarkdownFile[] {
    const updateByPath = new Map(updates.map((file) => [file.path, file]))
    const merged = current.map((file) => updateByPath.get(file.path) ?? file)
    const existingPaths = new Set(current.map((file) => file.path))
    for (const file of updates) {
        if (!existingPaths.has(file.path)) merged.push(file)
    }

    return merged
}

export function removeFilesByPath(files: MarkdownFile[], paths: string[]) {
    const pathSet = new Set(paths)

    return files.filter((file) => !pathSet.has(file.path))
}

export function reportCommitFlushFailure(error: unknown, dispatchChanged: () => void) {
    reportWorkspaceError(errorMessage(error, 'Commit failed'))
    telemetryService.captureError(error)
    dispatchChanged()
}

export function getProjectConfigOrNull(storage: StorageService | null): ProjectConfig | null {
    if (!storage) return null

    return resolveProjectConfigPaths(configService.getProjectConfig())
}

import type { Card, CardHeader, MarkdownFile } from '../../data/data_types'
import { generateUuid } from '../../data/uuid'

const HEADER_DELIMITER = '---'
const MARKDOWN_EXTENSION = '.md'
const DEFAULT_IMPORTED_STATUS = 'new'
const DEFAULT_IMPORTED_ID = 'F_0'
const TITLE_PREFIX = '# '
const LIST_ITEM_PREFIX = '  - '
const CHILD_INDENT = '  '

export type HeaderValue = string | string[] | Record<string, string>
export type MarkdownHeaderFields = Record<string, HeaderValue>

export interface ParsedMarkdown {
    body: string
    header: MarkdownHeaderFields
    rawHeader: string
}

export interface CardParseError {
    error: unknown
    path: string
}

export interface NewCardHeader {
    affects?: string[]
    /** Activity conversation references serialized through the existing `agents` frontmatter field. */
    agentLogReferences?: string[]
    author?: string | null
    id: string
    internalId: string
    owner?: string | null
    policy?: Record<string, boolean>
    status?: string | null
    title: string
}

interface HeaderSplit {
    body: string
    hasHeader: boolean
    rawHeader: string
}

interface CardSourceState {
    body: string
    content: string
    header: CardHeader
    headerFields: MarkdownHeaderFields
}

const sourceByCard = new WeakMap<Card, CardSourceState>()

function cloneCardHeader(header: CardHeader): CardHeader {
    return {
        ...header,
        affects: [...header.affects],
        agentLogReferences: [...header.agentLogReferences],
        policy: { ...header.policy },
    }
}

function requireCardSource(card: Card) {
    const source = sourceByCard.get(card)
    if (!source) throw new Error(`Cannot serialize card without parser source metadata: ${card.path}`)

    return source
}

function sameStringArray(left: string[], right: string[]) {
    return left.length === right.length && left.every((value, index) => value === right[index])
}

function sameBooleanMap(left: Record<string, boolean>, right: Record<string, boolean>) {
    const leftEntries = Object.entries(left)
    const rightEntries = Object.entries(right)

    return leftEntries.length === rightEntries.length && leftEntries.every(([key, value]) => right[key] === value)
}

function serializePolicy(policy: Record<string, boolean>) {
    return Object.fromEntries(Object.entries(policy).map(([key, enabled]) => [key, enabled ? 'true' : 'false']))
}

function setNullableHeaderField(fields: MarkdownHeaderFields, key: string, value: string | null) {
    if (value === null) delete fields[key]
    else fields[key] = value
}

function currentHeaderFields(card: Card, source: CardSourceState): MarkdownHeaderFields {
    const fields = cloneHeaderFields(source.headerFields)
    const { header } = card
    const sourceHeader = source.header

    if (!sameStringArray(header.affects, sourceHeader.affects)) fields.affects = [...header.affects]
    if (header.after !== sourceHeader.after) setNullableHeaderField(fields, 'after', header.after)
    if (!sameStringArray(header.agentLogReferences, sourceHeader.agentLogReferences)) fields.agents = [...header.agentLogReferences]
    if (header.author !== sourceHeader.author) setNullableHeaderField(fields, 'author', header.author)
    if (header.branch !== sourceHeader.branch) setNullableHeaderField(fields, 'branch', header.branch ?? null)
    if (header.id !== sourceHeader.id) fields.id = header.id
    if (header.internalId !== sourceHeader.internalId) setNullableHeaderField(fields, 'internalId', header.internalId)
    if (header.owner !== sourceHeader.owner) setNullableHeaderField(fields, 'owner', header.owner)
    if (!sameBooleanMap(header.policy, sourceHeader.policy)) fields.policy = serializePolicy(header.policy)
    if (header.status !== sourceHeader.status) setNullableHeaderField(fields, 'status', header.status)
    if (header.title !== sourceHeader.title) fields.title = header.title
    if (header.worktree !== sourceHeader.worktree || header.worktreeError !== sourceHeader.worktreeError) {
        if (header.worktree === null || header.worktree === undefined) delete fields.worktree
        else fields.worktree = String(header.worktree)
    }

    return fields
}

function detectLineEnding(content: string) {
    return content.includes('\r\n') ? '\r\n' : '\n'
}

function splitHeader(content: string): HeaderSplit {
    if (!content.startsWith(`${HEADER_DELIMITER}\n`) && !content.startsWith(`${HEADER_DELIMITER}\r\n`)) {
        return { body: content, hasHeader: false, rawHeader: '' }
    }

    const closingDelimiter = /\r?\n---\r?\n/g
    closingDelimiter.lastIndex = HEADER_DELIMITER.length
    const closingMatch = closingDelimiter.exec(content)

    if (!closingMatch) return { body: content, hasHeader: false, rawHeader: '' }

    const headerStart = content.indexOf('\n') + 1
    const rawHeader = content.slice(headerStart, closingMatch.index).replace(/\r\n/g, '\n')
    const body = content.slice(closingMatch.index + closingMatch[0].length)

    return { body, hasHeader: true, rawHeader }
}

function parseListValue(lines: string[], startIndex: number) {
    const values: string[] = []
    let index = startIndex + 1

    while (index < lines.length && lines[index].startsWith(LIST_ITEM_PREFIX)) {
        values.push(lines[index].slice(LIST_ITEM_PREFIX.length).trim())
        index += 1
    }

    return { nextIndex: index, values }
}

function parseMapValue(lines: string[], startIndex: number) {
    const value: Record<string, string> = {}
    let index = startIndex + 1

    while (index < lines.length && lines[index].startsWith(CHILD_INDENT) && !lines[index].startsWith(LIST_ITEM_PREFIX)) {
        const childLine = lines[index].trim()
        const separatorIndex = childLine.indexOf(':')

        if (separatorIndex === -1) break

        value[childLine.slice(0, separatorIndex).trim()] = childLine.slice(separatorIndex + 1).trim()
        index += 1
    }

    return { nextIndex: index, value }
}

function parseHeaderFields(headerText: string): MarkdownHeaderFields {
    const fields: MarkdownHeaderFields = {}
    const lines = headerText.split(/\r?\n/)
    let index = 0

    while (index < lines.length) {
        const line = lines[index]
        const separatorIndex = line.indexOf(':')

        if (separatorIndex === -1 || line.startsWith(' ')) {
            index += 1
            continue
        }

        const key = line.slice(0, separatorIndex).trim()
        const value = line.slice(separatorIndex + 1).trim()

        if (value.length > 0) {
            fields[key] = value
            index += 1
            continue
        }

        const nextLine = lines[index + 1] ?? ''

        if (nextLine.startsWith(LIST_ITEM_PREFIX)) {
            const listValue = parseListValue(lines, index)
            fields[key] = listValue.values
            index = listValue.nextIndex
            continue
        }

        if (nextLine.startsWith(CHILD_INDENT)) {
            const mapValue = parseMapValue(lines, index)
            fields[key] = mapValue.value
            index = mapValue.nextIndex
            continue
        }

        fields[key] = ''
        index += 1
    }

    return fields
}

function cloneHeaderFields(fields: MarkdownHeaderFields): MarkdownHeaderFields {
    return Object.fromEntries(Object.entries(fields).map(([key, value]) => {
        if (Array.isArray(value)) return [key, [...value]];
        if (typeof value === 'object') return [key, { ...value }];

        return [key, value];
    }));
}

function sameHeaderValue(left: HeaderValue | undefined, right: HeaderValue | undefined) {
    if (left === right) return true;
    if (left === undefined || right === undefined || typeof left !== typeof right) return false;
    if (typeof left === 'string' || typeof right === 'string') return false;
    if (Array.isArray(left) || Array.isArray(right)) {
        return Array.isArray(left)
            && Array.isArray(right)
            && left.length === right.length
            && left.every((value, index) => value === right[index]);
    }

    const leftEntries = Object.entries(left);
    const rightEntries = Object.entries(right);

    return leftEntries.length === rightEntries.length
        && leftEntries.every(([key, value]) => right[key] === value);
}

function getStringField(fields: MarkdownHeaderFields, fieldName: string) {
    const value = fields[fieldName]

    return typeof value === 'string' && value.length > 0 ? value : null
}

function getListField(fields: MarkdownHeaderFields, fieldName: string) {
    const value = fields[fieldName]

    return Array.isArray(value) ? value : []
}

function getMapField(fields: MarkdownHeaderFields, fieldName: string): Record<string, string> {
    const value = fields[fieldName]

    return value !== null && typeof value === 'object' && !Array.isArray(value) ? value : {}
}

function parsePolicyMap(fields: MarkdownHeaderFields): Record<string, boolean> {
    const policy = getMapField(fields, 'policy')

    return Object.fromEntries(Object.entries(policy).map(([key, value]) => [key, parsePolicyValue(value)]))
}

function parsePolicyValue(value: string) {
    const normalized = value.toLowerCase()

    // Invalid policy values parse as false until markdown parsing exposes warnings.
    return normalized === 'true'
}

function parseWorktree(fields: MarkdownHeaderFields) {
    const value = fields.worktree
    if (value === undefined) return { worktree: null, worktreeError: null, worktreeValue: null }
    if (typeof value !== 'string' || !/^[1-9]\d*$/u.test(value)) {
        return { worktree: null, worktreeError: `Invalid worktree value: ${String(value)}`, worktreeValue: String(value) }
    }

    const worktree = Number.parseInt(value, 10)
    if (!Number.isSafeInteger(worktree)) return { worktree: null, worktreeError: `Invalid worktree value: ${value}`, worktreeValue: value }

    return { worktree, worktreeError: null, worktreeValue: value }
}

function getTitleFromBody(body: string) {
    const titleLine = body.split(/\r?\n/).find((line) => line.startsWith(TITLE_PREFIX))

    return titleLine ? titleLine.slice(TITLE_PREFIX.length).trim() : 'Untitled'
}

function getFileName(path: string) {
    return path.split('/').at(-1) ?? path
}

function isMarkdownFile(path: string) {
    return path.toLowerCase().endsWith(MARKDOWN_EXTENSION)
}

function isRootWorkingFolderFile(path: string, workingFolder: string) {
    const normalizedPath = path.replace(/\\/g, '/')
    const prefix = `${workingFolder}/`
    const remainingPath = normalizedPath.startsWith(prefix) ? normalizedPath.slice(prefix.length) : normalizedPath

    return !remainingPath.includes('/') && isMarkdownFile(remainingPath)
}

function followsCardNamingConvention(path: string) {
    return /^[A-Z]+([_-])\d+\1.+\.md$/u.test(getFileName(path))
}

function parseCardHeader(fields: MarkdownHeaderFields, file: MarkdownFile, body: string): CardHeader {
    const fileName = getFileName(file.path)
    const fileId = fileName.match(/^([A-Z]+([_-])\d+)\2/u)?.[1] ?? null
    const id = getStringField(fields, 'id') ?? fileId ?? DEFAULT_IMPORTED_ID
    const title = getStringField(fields, 'title') ?? getTitleFromBody(body)
    const status = getStringField(fields, 'status') ?? (followsCardNamingConvention(file.path) ? null : DEFAULT_IMPORTED_STATUS)
    const worktree = parseWorktree(fields)

    return {
        affects: getListField(fields, 'affects'),
        after: getStringField(fields, 'after'),
        agentLogReferences: getListField(fields, 'agents'),
        author: getStringField(fields, 'author'),
        branch: getStringField(fields, 'branch'),
        id,
        internalId: getStringField(fields, 'internalId'),
        owner: getStringField(fields, 'owner'),
        policy: parsePolicyMap(fields),
        status,
        title,
        ...worktree,
    }
}

function rewriteHeaderLine(lines: string[], key: string, value: string) {
    const keyPrefix = `${key}:`
    const targetIndex = lines.findIndex((line) => !line.startsWith(' ') && line.slice(0, line.indexOf(':') + 1) === keyPrefix)

    if (targetIndex === -1) return [...lines, `${key}: ${value}`]

    const updated = [...lines]
    updated[targetIndex] = `${key}: ${value}`

    return updated
}

function removeHeaderField(lines: string[], key: string) {
    const keyIndex = lines.findIndex((line) => isHeaderKeyLine(line, key))
    if (keyIndex === -1) return lines

    const updated = [...lines]
    updated.splice(keyIndex, childBlockEndIndex(lines, keyIndex) - keyIndex)

    return updated
}

function isHeaderKeyLine(line: string, key: string) {
    return !line.startsWith(' ') && line.slice(0, line.indexOf(':') + 1) === `${key}:`
}

function rewritePolicyLines(lines: string[], key: string, value: string) {
    const childLine = `${CHILD_INDENT}${key}: ${value}`
    const policyIndex = lines.findIndex((line) => isHeaderKeyLine(line, 'policy'))

    if (policyIndex === -1) return [...lines, 'policy:', childLine]

    let childIndex = policyIndex + 1
    let lastChildIndex = policyIndex

    while (childIndex < lines.length && lines[childIndex].startsWith(CHILD_INDENT)) {
        const trimmed = lines[childIndex].trim()

        if (trimmed.slice(0, trimmed.indexOf(':')).trim() === key) {
            const updated = [...lines]
            updated[childIndex] = childLine

            return updated
        }

        lastChildIndex = childIndex
        childIndex += 1
    }

    const updated = [...lines]
    updated.splice(lastChildIndex + 1, 0, childLine)

    return updated
}

function childBlockEndIndex(lines: string[], startIndex: number) {
    let index = startIndex + 1

    while (index < lines.length && lines[index].startsWith(CHILD_INDENT)) index += 1

    return index
}

function rewriteListLines(lines: string[], key: string, values: string[]) {
    const keyLine = `${key}:`
    const nextLines = [keyLine, ...values.map((value) => `${LIST_ITEM_PREFIX}${value}`)]
    const keyIndex = lines.findIndex((line) => isHeaderKeyLine(line, key))

    if (keyIndex === -1) return [...lines, ...nextLines]

    const updated = [...lines]
    updated.splice(keyIndex, childBlockEndIndex(lines, keyIndex) - keyIndex, ...nextLines)

    return updated
}

function rewriteMapLines(lines: string[], key: string, values: Record<string, string>) {
    const keyLine = `${key}:`;
    const nextLines = [keyLine, ...Object.entries(values).map(([childKey, value]) => `${CHILD_INDENT}${childKey}: ${value}`)];
    const keyIndex = lines.findIndex((line) => isHeaderKeyLine(line, key));

    if (keyIndex === -1) return [...lines, ...nextLines];

    const updated = [...lines];
    updated.splice(keyIndex, childBlockEndIndex(lines, keyIndex) - keyIndex, ...nextLines);

    return updated;
}

function rewriteHeaderValue(content: string, key: string, value: HeaderValue | undefined) {
    const { body, hasHeader, rawHeader } = splitHeader(content);
    const lineEnding = detectLineEnding(content);
    const startingLines = hasHeader ? rawHeader.split('\n') : [];
    let nextLines: string[];

    if (value === undefined) nextLines = removeHeaderField(startingLines, key);
    else if (Array.isArray(value)) nextLines = rewriteListLines(startingLines, key, value);
    else if (typeof value === 'object') nextLines = rewriteMapLines(startingLines, key, value);
    else nextLines = rewriteHeaderLine(startingLines, key, value);

    if (hasHeader) return frameDocument(nextLines, body, lineEnding);

    return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding);
}

function frameDocument(headerLines: string[], body: string, lineEnding: string) {
    return `${HEADER_DELIMITER}${lineEnding}${headerLines.join(lineEnding)}${lineEnding}${HEADER_DELIMITER}${lineEnding}${body}`
}

function replaceCardBodyTitle(body: string, title: string) {
    return body.replace(/^# .*$/m, `${TITLE_PREFIX}${title}`)
}

function serializeNewHeader(header: NewCardHeader) {
    if (!header.id) throw new Error('Cannot generate a card without an id')
    if (!header.internalId) throw new Error('Cannot generate a card without an internalId')
    if (!header.title) throw new Error('Cannot generate a card without a title')

    const affects = header.affects ?? []
    const agentLogReferences = header.agentLogReferences ?? []
    const policy = header.policy ?? {}

    const lines: string[] = []
    lines.push(`author: ${header.author ?? ''}`)
    lines.push(`id: ${header.id}`)
    lines.push(`internalId: ${header.internalId}`)
    lines.push(`title: ${header.title}`)
    lines.push(`status: ${header.status ?? DEFAULT_IMPORTED_STATUS}`)
    lines.push(`owner: ${header.owner ?? ''}`)
    lines.push('affects:', ...affects.map((entry) => `${LIST_ITEM_PREFIX}${entry}`))
    lines.push('agents:', ...agentLogReferences.map((entry) => `${LIST_ITEM_PREFIX}${entry}`))
    lines.push('policy:', ...Object.entries(policy).map(([key, value]) => `${CHILD_INDENT}${key}: ${value ? 'true' : 'false'}`))

    return lines.join('\n')
}

export const markdownParsingService = {
    followsCardNamingConvention,

    isMarkdownFile,

    isRootWorkingFolderFile,

    parse(content: string): ParsedMarkdown {
        const { body, rawHeader } = splitHeader(content)

        return { body, header: parseHeaderFields(rawHeader), rawHeader }
    },

    /**
     * Parses a markdown file into a card. `isActive` marks the working folder root files,
     * which are the only ones that are always cards and always get an `internalId`.
     * Archived and released files are cards when they already carry an `internalId`;
     * all other markdown is a regular document that never receives one.
     * See the card classification rule in design/architecture/current_data_model.md.
     */
    parseCard(file: MarkdownFile, workingFolder: string): Card {
        const { body, hasHeader, rawHeader } = splitHeader(file.content)
        const fields = parseHeaderFields(rawHeader)
        const header = parseCardHeader(fields, file, body)
        const card: Card = {
            agentConversationErrors: [],
            agentConversations: [],
            content: body,
            hasFrontmatter: hasHeader,
            header,
            isActive: isRootWorkingFolderFile(file.path, workingFolder),
            path: file.path,
            sha: file.sha,
        }
        sourceByCard.set(card, { body, content: file.content, header: cloneCardHeader(header), headerFields: cloneHeaderFields(fields) })

        return card
    },

    serializeCard(card: Card): MarkdownFile {
        const source = requireCardSource(card)
        const headerFields = currentHeaderFields(card, source)
        const keys = [...new Set([...Object.keys(source.headerFields), ...Object.keys(headerFields)])]
        let content = source.content

        for (const key of keys) {
            const sourceValue = source.headerFields[key]
            const currentValue = headerFields[key]
            if (sameHeaderValue(sourceValue, currentValue)) continue

            content = rewriteHeaderValue(content, key, currentValue)
        }
        if (card.content !== source.body) content = this.replaceBody(content, card.content)

        return { content, path: card.path, ...(card.sha ? { sha: card.sha } : {}) }
    },

    acknowledgeSerializedCard(card: Card, file: MarkdownFile) {
        const { body, rawHeader } = splitHeader(file.content)
        const headerFields = parseHeaderFields(rawHeader)
        sourceByCard.set(card, {
            body,
            content: file.content,
            header: parseCardHeader(headerFields, file, body),
            headerFields: cloneHeaderFields(headerFields),
        })
    },

    hasSourceContent(card: Card, content: string) {
        return sourceByCard.get(card)?.content === content
    },

    splitCards(files: MarkdownFile[], workingFolder: string) {
        const markdownFiles = files.filter((file) => isMarkdownFile(file.path))
        const activeCards: Card[] = []
        const backgroundCards: Card[] = []
        const parseErrors: CardParseError[] = []

        for (const file of markdownFiles) {
            try {
                const card = this.parseCard(file, workingFolder)
                const targetCards = card.isActive ? activeCards : backgroundCards
                targetCards.push(card)
            } catch (error) {
                parseErrors.push({ error, path: file.path })
            }
        }

        return { activeCards, backgroundCards, parseErrors }
    },

    replaceBody(content: string, body: string) {
        const { hasHeader, rawHeader } = splitHeader(content)

        if (!hasHeader) return body

        return frameDocument(rawHeader.split('\n'), body, detectLineEnding(content))
    },

    rewriteHeader(content: string, updates: Record<string, string>) {
        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = Object.entries(updates).reduce(
            (lines, [key, value]) => rewriteHeaderLine(lines, key, value),
            startingLines,
        )

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    setCardTitle(content: string, title: string) {
        const contentWithHeaderTitle = this.rewriteHeader(content, { title })
        const { body, rawHeader } = splitHeader(contentWithHeaderTitle)

        return frameDocument(rawHeader.split('\n'), replaceCardBodyTitle(body, title), detectLineEnding(contentWithHeaderTitle))
    },

    setPolicyFlag(content: string, key: string, enabled: boolean) {
        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = rewritePolicyLines(startingLines, key, enabled ? 'true' : 'false')

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    setAgentLogReferences(content: string, references: string[]) {
        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = rewriteListLines(startingLines, 'agents', references)

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    setAffects(content: string, affects: string[]) {
        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = rewriteListLines(startingLines, 'affects', affects)

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    setBranch(content: string, branch: string | null) {
        if (branch !== null && branch.length === 0) throw new Error('Missing card branch name')

        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = branch === null
            ? removeHeaderField(startingLines, 'branch')
            : rewriteHeaderLine(startingLines, 'branch', branch)

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    setWorktree(content: string, worktree: number | null) {
        if (worktree !== null && (!Number.isSafeInteger(worktree) || worktree <= 0)) {
            throw new Error(`Invalid card worktree index: ${worktree}`)
        }

        const { body, hasHeader, rawHeader } = splitHeader(content)
        const lineEnding = detectLineEnding(content)
        const startingLines = hasHeader ? rawHeader.split('\n') : []
        const nextLines = worktree === null
            ? removeHeaderField(startingLines, 'worktree')
            : rewriteHeaderLine(startingLines, 'worktree', String(worktree))

        if (hasHeader) return frameDocument(nextLines, body, lineEnding)

        return frameDocument(nextLines, `${lineEnding}${content}`, lineEnding)
    },

    buildCardMarkdown(header: NewCardHeader, body: string) {
        return `${HEADER_DELIMITER}\n${serializeNewHeader(header)}\n${HEADER_DELIMITER}\n\n${body}`
    },

    generateInternalId() {
        return generateUuid()
    },
}

import {
    Box,
    Button,
    CircularProgress,
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Stack,
    Tab,
    Tabs,
    Typography,
    useMediaQuery,
    useTheme,
} from '@mui/material'
import { useEffect, useMemo, useRef, useState, useSyncExternalStore } from 'react'
import { navigateTo } from '../../app/app_navigation'
import { CONFIG_SECTIONS, configService, type ConfigEntry, type ConfigKey } from '../../services/config/config_service'
import { saveDesktopConfigToHost } from '../../services/config/desktop_config_transport'
import { dataService } from '../../services/data/data_service'
import { dialogService } from '../../services/dialog_service'
import { DesktopConfigSection } from './desktop_config_section'
import { ProjectConfigSection } from './project_config_section'
import { ReactConfigSection } from './react_config_section'
import { useAppTheme } from '../../theme/use_app_theme'
import {
    cloneMarkdownStyleConfig,
    isMarkdownStyleConfig,
    isMarkdownStylePresetName,
    type MarkdownStyleConfig,
    type MarkdownStyleName,
} from '../../theme/theme_config'
import { MarkdownConfigSection } from './markdown_config_section'
import { agentCapabilitiesService } from '../../services/agents/agent_capabilities_service'
import { getElectronRemoteControlBridge } from '../../data/electron_remote_control_bridge'
import { useProjectReadOnly } from '../hooks/use_project_read_only'
import { useWorktreeDraft } from '../hooks/use_worktrees'
import { worktreeService } from '../../services/project/worktree_service'

const CONFIG_PAGE_PADDING = 3
const CONFIG_FORM_MAX_WIDTH = 720
const CONFIG_SIDEBAR_WIDTH = 220
const DRAFT_DISCARD_DELAY_MS = 0
const MARKDOWN_CONFIG_SECTION = { id: 'markdown', label: 'Markdown' }
let configPageMountGeneration = 0

interface MarkdownStyleDraft {
    config: MarkdownStyleConfig
    name: MarkdownStyleName
}

interface ConfigPageProps {
    hash: string
}

function getActiveSection(hash: string, sections: typeof CONFIG_SECTIONS) {
    if (sections.length === 0) return null

    const section = hash.replace('#', '')
    if (sections.some((item) => item.id === section)) return section

    return sections[0]?.id ?? null
}

function getVisibleSections(entries: ConfigEntry[]) {
    return CONFIG_SECTIONS.flatMap((section) => {
        const visibleSection = entries.some((entry) => entry.section === section.id) ? [section] : []
        return section.id === 'react' ? [...visibleSection, MARKDOWN_CONFIG_SECTION] : visibleSection
    })
}

function getConfigDraftSnapshot() {
    return configService.getDraft()
}

function subscribeToConfigChanges(onStoreChange: () => void) {
    configService.addEventListener('changed', onStoreChange)

    return () => configService.removeEventListener('changed', onStoreChange)
}

export function ConfigPage(props: ConfigPageProps) {
    const { hash } = props
    const theme = useTheme()
    const isMobile = useMediaQuery(theme.breakpoints.down('md'))
    const readOnly = useProjectReadOnly()
    const {
        markdownStyle,
        markdownStyleConfig,
        setCustomMarkdownStyle,
        setMarkdownStyle,
    } = useAppTheme()
    const draft = useSyncExternalStore(subscribeToConfigChanges, getConfigDraftSnapshot)
    const worktreeDraft = useWorktreeDraft()
    const [invalidConfigKeys, setInvalidConfigKeys] = useState<Set<ConfigKey>>(() => new Set())
    const [isSaving, setIsSaving] = useState(false)
    const [markdownStyleDraft, setMarkdownStyleDraft] = useState<MarkdownStyleDraft>(() => ({
        config: cloneMarkdownStyleConfig(markdownStyleConfig),
        name: markdownStyle,
    }))
    const draftDiscardTimeoutRef = useRef<number | null>(null)
    const entries = configService.getEntries()
    const visibleSections = useMemo(() => getVisibleSections(entries), [entries])
    const activeSection = getActiveSection(hash, visibleSections)
    const markdownStyleChanged = markdownStyleDraft.name !== markdownStyle
        || JSON.stringify(markdownStyleDraft.config) !== JSON.stringify(markdownStyleConfig)
    const markdownStyleValid = isMarkdownStyleConfig(markdownStyleDraft.config)

    useEffect(() => {
        if (visibleSections.length === 0) dialogService.error('Config page requires at least one visible section')
    }, [visibleSections.length])

    useEffect(() => {
        configPageMountGeneration += 1
        const mountGeneration = configPageMountGeneration
        if (draftDiscardTimeoutRef.current !== null) {
            window.clearTimeout(draftDiscardTimeoutRef.current)
            draftDiscardTimeoutRef.current = null
        }

        const currentDraft = configService.getDraft()
        if (!currentDraft) configService.loadDraft()
        if (worktreeService.isSupported()) worktreeService.startDraft()
        return () => {
            // React StrictMode mounts, unmounts, and remounts effects; delay discard so the remount can cancel it.
            draftDiscardTimeoutRef.current = window.setTimeout(() => {
                if (configPageMountGeneration !== mountGeneration) return
                configService.discardDraft()
                worktreeService.discardDraft()
                draftDiscardTimeoutRef.current = null
            }, DRAFT_DISCARD_DELAY_MS)
        }
    }, [])

    if (!draft) return null

    const handleValueChange = (key: ConfigKey, value: unknown) => {
        try {
            if (
                key === 'project.cardSeparator'
                && value !== draft[key]
                && value !== configService.get('project.cardSeparator')
            ) {
                dialogService.warning(
                    'Saving this change will rename existing card files and update their IDs.',
                    { critical: true, title: 'Card files will be renamed' },
                )
            }
            configService.setDraftValue(key, value)
        } catch (error) {
            dialogService.error(error, { fallbackMessage: 'Invalid config value' })
        }
    }

    const handleValidityChange = (key: ConfigKey, valid: boolean) => {
        setInvalidConfigKeys((currentKeys) => {
            if (valid && !currentKeys.has(key)) return currentKeys
            if (!valid && currentKeys.has(key)) return currentKeys

            const nextKeys = new Set(currentKeys)
            if (valid) nextKeys.delete(key)
            else nextKeys.add(key)

            return nextKeys
        })
    }

    const handleMarkdownStyleChange = (name: MarkdownStyleName, config: MarkdownStyleConfig) => {
        setMarkdownStyleDraft({ config, name })
    }

    const handleSaveClick = async () => {
        setIsSaving(true)
        let applyingWorktrees = !!worktreeDraft
            && (worktreeDraft.additions.length > 0 || worktreeDraft.removals.length > 0)
        try {
            if (applyingWorktrees) await worktreeService.applyDraft()
            applyingWorktrees = false
            const shouldSaveProjectConfig = configService.hasDraftChangesForSource('project')
            const shouldSaveDesktopConfig = configService.hasDraftChangesForSource('desktop')
            const previousCardSeparator = configService.get('project.cardSeparator')
            const nextCardSeparator = draft['project.cardSeparator']
            const remoteControlBridge = getElectronRemoteControlBridge()
            const remoteControlPortChanged = configService.hasDesktopConfig()
                && configService.get('desktop.remoteControlPort') !== draft['desktop.remoteControlPort']
            const shouldRestartRemoteControl = remoteControlPortChanged
                && remoteControlBridge
                && (await remoteControlBridge.getStatus()).active
            const shouldUpdateCardSeparator = configService.hasProjectConfig()
                && previousCardSeparator !== nextCardSeparator
            if (shouldUpdateCardSeparator) {
                await dataService.projectLoading.updateCardSeparator(previousCardSeparator, nextCardSeparator)
            }
            if (shouldSaveDesktopConfig && configService.hasDesktopConfig()) {
                const persistedDesktopConfig = await saveDesktopConfigToHost(configService.getDraftDesktopValues())
                configService.replaceDesktopConfig(persistedDesktopConfig)
                await agentCapabilitiesService.reload()
            }
            configService.saveDraft()
            configService.loadDraft()
            if (markdownStyleChanged && markdownStyleDraft.name === 'custom') setCustomMarkdownStyle(markdownStyleDraft.config)
            else if (markdownStyleChanged && isMarkdownStylePresetName(markdownStyleDraft.name)) {
                setMarkdownStyle(markdownStyleDraft.name)
            }
            if (shouldSaveProjectConfig && configService.hasProjectConfig()) await dataService.projectLoading.saveProjectConfig()
            navigateTo('/')
            if (shouldRestartRemoteControl) {
                try {
                    await remoteControlBridge.stop()
                    await remoteControlBridge.start()
                } catch (error) {
                    dialogService.error(error, { fallbackMessage: 'Remote-control restart failed' })
                    return
                }
            }
            dialogService.success('Config saved')
        } catch (error) {
            dialogService.error(error, { fallbackMessage: applyingWorktrees ? 'Worktree setup failed' : 'Config save failed' })
        } finally {
            setIsSaving(false)
        }
    }

    const handleCancelClick = () => {
        configService.discardDraft()
        worktreeService.discardDraft()
        navigateTo('/')
    }

    const sectionProps = {
        draft,
        entries,
        onChange: handleValueChange,
        onValidityChange: handleValidityChange,
    }

    const sectionTabs = (
        <Tabs
            aria-label="Config sections"
            orientation={isMobile ? 'horizontal' : 'vertical'}
            scrollButtons="auto"
            value={activeSection ?? false}
            variant="scrollable"
        >
            {visibleSections.map((section) => (
                <Tab component="a" href={`#/config/${section.id}`} key={section.id} label={section.label} value={section.id} />
            ))}
        </Tabs>
    )

    return (
        <Dialog
            aria-labelledby="config-dialog-title"
            fullScreen={isMobile}
            fullWidth
            maxWidth="lg"
            onClose={isSaving ? undefined : handleCancelClick}
            open
        >
            <DialogTitle id="config-dialog-title" sx={{ borderBottom: 1, borderColor: 'divider' }}>
                Config
            </DialogTitle>
            <DialogContent
                aria-label="Config dialog body"
                sx={{ display: 'flex', minHeight: 0, overflow: 'hidden', p: 0 }}
            >
                {!isMobile ? (
                    <Box
                        aria-label="Config section navigation"
                        component="nav"
                        sx={{ borderRight: 1, borderColor: 'divider', flexShrink: 0, minHeight: 0, overflow: 'auto', width: CONFIG_SIDEBAR_WIDTH }}
                        tabIndex={0}
                    >
                        {sectionTabs}
                    </Box>
                ) : null}
                <Box
                    aria-label="Config section content"
                    role="region"
                    sx={{ flex: 1, minHeight: 0, minWidth: 0, overflow: 'auto', p: CONFIG_PAGE_PADDING }}
                    tabIndex={0}
                >
                    <Stack spacing={3} sx={{ maxWidth: CONFIG_FORM_MAX_WIDTH }}>
                        {isMobile ? sectionTabs : null}

                        {activeSection === 'react' ? <ReactConfigSection {...sectionProps} /> : null}
                        {activeSection === 'markdown' ? (
                            <MarkdownConfigSection
                                config={markdownStyleDraft.config}
                                name={markdownStyleDraft.name}
                                onChange={handleMarkdownStyleChange}
                            />
                        ) : null}
                        {activeSection === 'project' ? <ProjectConfigSection {...sectionProps} disabled={readOnly} /> : null}
                        {activeSection === 'desktop' ? <DesktopConfigSection {...sectionProps} disabled={!configService.hasDesktopConfig()} /> : null}
                    </Stack>
                </Box>
            </DialogContent>
            <DialogActions sx={{ bgcolor: 'background.default', borderTop: 1, borderColor: 'divider' }}>
                {worktreeDraft?.applying ? (
                    <Stack direction="row" spacing={1} sx={{ alignItems: 'center' }}>
                        <CircularProgress size={20} />
                        <Typography variant="body2">Setting up worktrees with Git...</Typography>
                    </Stack>
                ) : null}
                <Button disabled={isSaving} onClick={handleCancelClick} variant="outlined">
                    Cancel
                </Button>
                <Button disabled={isSaving || invalidConfigKeys.size > 0 || !markdownStyleValid} onClick={handleSaveClick} variant="contained">
                    Save
                </Button>
            </DialogActions>
        </Dialog>
    )
}

import type { ConfigSectionProps } from './config_section_props'
import { ConfigSectionLayout } from './config_section_layout'
