function createMemoryStorage(initialToken: string | null = null): AuthStorage {
    const items = new Map<string, string>()

    if (initialToken) items.set(AUTH_TOKEN_STORAGE_KEY, initialToken)

    return {
        getItem: (key) => items.get(key) ?? null,
        removeItem: (key) => {
            items.delete(key)
        },
        setItem: (key, value) => {
            items.set(key, value)
        },
    }
}

