        `id: ${id.toUpperCase()}`,
        `internalId: ${id}`,
        `title: ${id.toUpperCase()}`,
        `status: ${options.status ?? 'todo'}`,
        ...(options.after ? [`after: ${options.after}`] : []),
        '---',
